 * icmp6_ndisc_adv_addopt
 * @ctx:	socket buffer
 *
 * Make room at the tail of the packet for the ND_OPT_TARGET_LL_ADDR option
 * (Type+Length + MAC addr = 8 byte) when the original Neighbour Solicitation
 * did not carry a source link-layer address option. The new bytes are zeroed
 * so that the checksum stays additive when the old options are read back.
 */
static __always_inline int icmp6_ndisc_adv_addopt(struct __ctx_buff *ctx)
{
	struct ipv6hdr *ip6;
	void *data, *data_end;
	__u64 *opt;

	if (ctx_change_tail(ctx, (__u32)(ctx_full_len(ctx) + ICMP6_ND_OPT_LEN), 0) < 0)
		return DROP_INVALID;

	if (!revalidate_data(ctx, &data, &data_end, &ip6))
		return DROP_INVALID;

	ip6->payload_len = bpf_htons(bpf_ntohs(ip6->payload_len)
							+ ICMP6_ND_OPT_LEN);

	/* 0 options pkt to make sure csum is additive when read old_opts */
	opt = (__u64 *)((void *)(ip6 + 1) + sizeof(struct icmp6hdr)
							+ sizeof(union v6addr));
	if ((void *)(opt + 1) > data_end)
		return DROP_INVALID;
	*opt = 0x0ULL;

	return 0;
}

